          "The current site also presents creator routes for affiliate links and campaign opportunities. These explain ecosystem roles without establishing that a brand entering one route has acquired software for managing every partnership.\n\nIf a colleague lands on a creator page from search, identify whom it serves and the intended action before returning to the brand’s assignment. Similar marketing language across routes does not change the underlying user or object.\n\nSuch pages do not establish that an individual creator applied, received an invitation, is available or accepts a brand’s terms. Required relationships and states still need their corresponding records.\n\nWe have applied for no opportunity, joined no program and submitted no contact form. The output of navigation research is knowing which information to inspect and what to ask next, rather than creating a relationship or obligation without the relevant assignment. It should make the subsequent conversation better informed while keeping an observed route separate from an action actually completed by a user."
