          "Record the question, metric definition, original source, observation window, distribution and unknowns before writing the conclusion those materials support. The table and checklist organize information without automatically verifying interaction provenance.\n\nThe useful lesson from free-like claims is to distinguish obtaining more actions from understanding an actual result. Improve explanations, choose a suitable comparison and continue checking evidence without adding a growth promise or personal accusation to give a limited observation more weight. A clear statement of uncertainty is part of an informative result when the underlying source cannot answer the larger question."
